package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="student_bus_allocations",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","route_id"})) @Data @Builder @NoArgsConstructor @AllArgsConstructor public class StudentBusAllocation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) Student student; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="bus_id",nullable=false) Bus bus; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="route_id",nullable=false) BusRoute route; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="pickup_point_id",nullable=false) PickupPoint pickupPoint; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="drop_point_id",nullable=false) PickupPoint dropPoint; @Column(length=20) String status; @Column(name="allocated_at") LocalDateTime allocatedAt; @PrePersist void create(){allocatedAt=LocalDateTime.now();if(status==null)status="ACTIVE";} }
